export default {
	async asyncData({ $content, params }) {
		const details = await $content(`westwood/${params.slug}`).fetch();

		return {
			details
		}
	},
	head() {
		if(this.details) {
			return {
				title: this.details.pageTitle,
				meta: [
					{
					hid: 'description',
					name: 'description',
					content: this.details.pageDescription
					}
				],
			}
		}
	}
}
